1	import * as React from "react";
2	import { type LucideIcon } from "lucide-react";
3	import { Card } from "@/components/ui/Card";
4	
5	/**
6	 * A labeled number (not a chart) — the accessibility-first way to surface a
7	 * metric. The label and value are plain text, read in order by a screen reader.
8	 */
9	export function StatCard({
10	  label,
11	  value,
12	  hint,
13	  icon: Icon,
14	}: {
15	  label: string;
16	  value: string | number;
17	  hint?: string;
18	  icon?: LucideIcon;
19	}) {
20	  return (
21	    <Card className="flex flex-col gap-1">
22	      <div className="flex items-center gap-2">
23	        {Icon ? (
24	          <Icon size={18} strokeWidth={2} aria-hidden="true" className="text-ink-soft" />
25	        ) : null}
26	        <span className="text-sm font-bold text-ink-soft">{label}</span>
27	      </div>
28	      <span className="font-display text-h1 text-ink">{value}</span>
29	      {hint ? <span className="text-sm text-ink-soft">{hint}</span> : null}
30	    </Card>
31	  );
32	}
